import { useMemo, useState, type FormEvent } from "react";
import {
  AlertTriangle, ArrowLeftRight, BarChart3, Bell, CalendarDays, Car, Check, ChevronRight,
  CircleDollarSign, Clock3, Download, Eye, GraduationCap, Home, LoaderCircle, LogOut,
  MapPin, Menu, Moon, Navigation, Pencil, Phone, Plus, QrCode, RefreshCw, Search, Settings,
  ShieldCheck, Sparkles, Star, Sun, Trash2, UserRound, Users, WalletCards, X,
} from "lucide-react";
import { toast } from "sonner";
import { useUniCarona } from "@/hooks/use-unicarona";
import { campuses, initialState, type Ride, type RideStatus, type User, type View } from "@/lib/unicarona-data";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

const inputClass = "h-11 bg-background";
const universityOptions = ["PUC Minas Coração Eucarístico", "PUC Praça da Liberdade", "UFMG Pampulha", "CEFET-MG Nova Suíça", "PUC Minas Barreiro"];
const menu: { id: View; label: string; icon: typeof Home }[] = [
  { id: "inicio", label: "Início", icon: Home }, { id: "buscar", label: "Buscar carona", icon: Search },
  { id: "publicar", label: "Publicar", icon: Plus }, { id: "solicitacoes", label: "Solicitações", icon: Users },
  { id: "corrida", label: "Corrida ao vivo", icon: Navigation }, { id: "carteira", label: "Carteira", icon: WalletCards },
  { id: "painel", label: "Painel", icon: BarChart3 }, { id: "perfil", label: "Perfil", icon: UserRound },
];

function Field({ label, error, valid, children }: { label: string; error?: string; valid?: boolean; children: React.ReactNode }) {
  return <div className="space-y-1.5"><div className="flex items-center justify-between"><Label>{label}</Label>{valid && <span className="flex items-center gap-1 text-xs font-semibold text-success"><Check className="size-3" /> Válido</span>}</div>{children}{error && <p className="flex items-center gap-1 text-xs font-medium text-destructive"><AlertTriangle className="size-3" />{error}</p>}</div>;
}

function Status({ value }: { value: RideStatus | "Recusada" }) {
  const styles: Record<string, string> = { "Pendente": "bg-warning-soft text-warning", "Aprovada": "bg-success-soft text-success", "Em andamento": "bg-primary-soft text-primary", "Concluída": "bg-muted text-muted-foreground", "Cancelada": "bg-destructive-soft text-destructive", "Recusada": "bg-destructive-soft text-destructive" };
  return <Badge variant="outline" className={`border-0 ${styles[value]}`}>{value}</Badge>;
}

function Login({ onLogin, onSignup }: { onLogin: (email: string, password: string) => boolean; onSignup: (user: User) => void }) {
  const [signup, setSignup] = useState(false);
  const [email, setEmail] = useState("bruno.andrade@pucminas.br");
  const [password, setPassword] = useState("unicarona123");
  const [name, setName] = useState(""); const [phone, setPhone] = useState(""); const [university, setUniversity] = useState(universityOptions[0]);
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const validAcademic = /^[^\s@]+@(?:[^\s@]+\.)?(?:edu\.br|pucminas\.br|ufmg\.br|cefetmg\.br)$/i.test(email);
  const maskPhone = (v: string) => { const d = v.replace(/\D/g, "").slice(0, 11); return d.replace(/^(\d{2})(\d)/, "($1) $2").replace(/(\d{5})(\d)/, "$1-$2"); };
  const submit = (e: FormEvent) => {
    e.preventDefault(); setError("");
    if (!validAcademic) return setError("Use um e-mail acadêmico institucional válido.");
    if (signup && (name.trim().length < 3 || phone.length < 15 || password.length < 8)) return setError("Revise os campos. A senha precisa ter pelo menos 8 caracteres.");
    setBusy(true);
    window.setTimeout(() => {
      if (signup) onSignup({ id: `u-${Date.now()}`, name: name.trim(), email, password, university, phone, bio: "Novo membro da comunidade UniCarona.", course: "Estudante", avatar: name.split(" ").map((p) => p[0]).slice(0, 2).join("").toUpperCase(), rating: 5, completedRides: 0, type: "passageira", walletConfigured: false });
      else if (!onLogin(email, password)) setError("E-mail ou senha incorretos. Tente novamente.");
      setBusy(false);
    }, 650);
  };
  return <main className="min-h-screen bg-auth px-4 py-8 sm:grid sm:place-items-center">
    <div className="mx-auto grid w-full max-w-5xl overflow-hidden rounded-lg border bg-card shadow-2xl lg:grid-cols-[.9fr_1.1fr]">
      <section className="hidden min-h-[680px] flex-col justify-between bg-brand-panel p-10 text-primary-foreground lg:flex">
        <div className="flex items-center gap-3 text-xl font-bold"><span className="grid size-10 place-items-center rounded-md bg-primary-foreground/15"><Car /></span>UniCarona</div>
        <div><Badge className="mb-5 bg-primary-foreground/15 text-primary-foreground">Mobilidade universitária</Badge><h1 className="text-4xl font-bold leading-tight">Seu caminho para a faculdade pode ser compartilhado.</h1><p className="mt-4 max-w-md text-primary-foreground/75">Caronas seguras entre estudantes verificados de Belo Horizonte.</p></div>
        <div className="flex items-center gap-3 text-sm text-primary-foreground/75"><ShieldCheck /> Comunidade acadêmica verificada</div>
      </section>
      <section className="p-6 sm:p-10 lg:p-12">
        <div className="mb-8 flex items-center gap-3 lg:hidden"><span className="grid size-10 place-items-center rounded-md bg-primary text-primary-foreground"><Car /></span><span className="text-xl font-bold">UniCarona</span></div>
        <p className="text-sm font-semibold text-primary">{signup ? "COMECE AGORA" : "BEM-VINDO DE VOLTA"}</p>
        <h2 className="mt-2 text-3xl font-bold">{signup ? "Crie sua conta" : "Entre na sua conta"}</h2>
        <p className="mt-2 text-sm text-muted-foreground">{signup ? "Uma conta para pedir e oferecer caronas." : "Use seu e-mail acadêmico para continuar."}</p>
        <form onSubmit={submit} className="mt-8 space-y-5">
          {signup && <><Field label="Nome completo"><Input className={inputClass} maxLength={80} value={name} onChange={(e) => setName(e.target.value)} placeholder="Como aparece na universidade" /></Field>
          <div className="grid gap-4 sm:grid-cols-2"><Field label="Universidade"><Select value={university} onValueChange={setUniversity}><SelectTrigger className={inputClass}><SelectValue /></SelectTrigger><SelectContent>{universityOptions.map((u) => <SelectItem value={u} key={u}>{u}</SelectItem>)}</SelectContent></Select></Field><Field label="Telefone celular"><Input className={inputClass} value={phone} onChange={(e) => setPhone(maskPhone(e.target.value))} placeholder="(31) 99999-9999" /></Field></div></>}
          <Field label="E-mail acadêmico" valid={validAcademic} error={email && !validAcademic ? "Informe um domínio acadêmico, como @ufmg.br." : undefined}><Input className={inputClass} type="email" maxLength={120} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="seu.nome@universidade.edu.br" /></Field>
          <Field label="Senha"><Input className={inputClass} type="password" maxLength={80} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Mínimo de 8 caracteres" />{signup && <div className="grid grid-cols-3 gap-1 pt-1"><span className={`h-1 rounded-full ${password.length > 0 ? "bg-destructive" : "bg-muted"}`} /><span className={`h-1 rounded-full ${password.length >= 8 ? "bg-warning" : "bg-muted"}`} /><span className={`h-1 rounded-full ${password.length >= 12 ? "bg-success" : "bg-muted"}`} /></div>}</Field>
          {error && <div className="rounded-md bg-destructive-soft p-3 text-sm text-destructive">{error}</div>}
          <Button className="h-11 w-full" disabled={busy}>{busy ? <LoaderCircle className="animate-spin" /> : signup ? "Criar minha conta" : "Entrar"}</Button>
        </form>
        <button className="mt-6 w-full text-sm font-semibold text-primary" onClick={() => { setSignup(!signup); setError(""); }}>{signup ? "Já tenho uma conta" : "Ainda não tenho conta — cadastrar"}</button>
        {!signup && <p className="mt-5 rounded-md bg-muted p-3 text-xs text-muted-foreground"><b>Demonstração:</b> Bruno ou Camila usam a senha <b>unicarona123</b>.</p>}
      </section>
    </div>
  </main>;
}

function RideCard({ ride, driver, onProfile, onRequest, own, onEdit, onCancel }: { ride: Ride; driver: User; onProfile?: () => void; onRequest?: () => void; own?: boolean; onEdit?: () => void; onCancel?: () => void }) {
  return <article className="ride-card border bg-card p-5 shadow-sm">
    <div className="grid grid-cols-[minmax(0,1fr)_auto] gap-3"><button className="flex min-w-0 items-center gap-3 text-left" onClick={onProfile}><Avatar><AvatarFallback className="bg-primary-soft font-bold text-primary">{driver.avatar}</AvatarFallback></Avatar><span className="min-w-0"><b className="block truncate text-sm">{driver.name}</b><span className="flex items-center gap-1 text-xs text-muted-foreground"><Star className="size-3 fill-warning text-warning" /> {ride.rating} · {driver.university}</span></span></button><Status value={ride.status} /></div>
    <div className="relative my-5 space-y-4 pl-7 before:absolute before:left-[7px] before:top-3 before:h-[calc(100%-22px)] before:border-l before:border-dashed before:border-primary/40"><div className="relative text-sm before:absolute before:-left-7 before:top-1 before:size-3 before:rounded-full before:border-4 before:border-primary-soft before:bg-primary"><span className="block text-xs text-muted-foreground">Origem</span><b>{ride.origin}</b></div><div className="relative text-sm before:absolute before:-left-7 before:top-1 before:size-3 before:rounded-full before:bg-success"><span className="block text-xs text-muted-foreground">Destino</span><b>{ride.destination}</b></div></div>
    <div className="flex flex-wrap items-center gap-x-4 gap-y-2 border-t pt-4 text-sm text-muted-foreground"><span className="flex items-center gap-1.5"><CalendarDays className="size-4" /> {new Date(`${ride.date}T12:00`).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" })}</span><span className="flex items-center gap-1.5"><Clock3 className="size-4" /> {ride.time}</span><span className="flex items-center gap-1.5"><Users className="size-4" /> {ride.seats} {ride.seats === 1 ? "vaga" : "vagas"}</span><b className="ml-auto text-foreground">R$ 6,00</b></div>
    <div className="mt-4 flex gap-2">{own ? <><Button variant="outline" className="flex-1" onClick={onEdit}><Pencil /> Editar</Button><Button variant="destructive" className="flex-1" onClick={onCancel}><X /> Cancelar</Button></> : <Button className="w-full" disabled={ride.seats === 0 || ride.status !== "Pendente"} onClick={onRequest}>Solicitar vaga <ChevronRight /></Button>}</div>
  </article>;
}

function StatCard({ icon: Icon, label, value, note }: { icon: typeof Home; label: string; value: string; note: string }) {
  return <div className="border bg-card p-5 shadow-sm"><div className="mb-5 grid size-10 place-items-center rounded-md bg-primary-soft text-primary"><Icon /></div><p className="text-sm text-muted-foreground">{label}</p><p className="mt-1 text-2xl font-bold">{value}</p><p className="mt-2 text-xs font-medium text-success">{note}</p></div>;
}

export function UniCaronaApp() {
  const { state, update, reset, hydrated } = useUniCarona();
  const [view, setView] = useState<View>("inicio"); const [mobileMenu, setMobileMenu] = useState(false);
  const [modal, setModal] = useState<"driver" | "request" | "wallet" | "receipt" | null>(null);
  const [selectedRideId, setSelectedRideId] = useState("r3"); const [confirm, setConfirm] = useState<"logout" | "delete" | "cancel" | "reject" | null>(null);
  const [searching, setSearching] = useState(false);
  const current = state.users.find((u) => u.id === state.currentUserId) ?? null;
  const selectedRide = state.rides.find((r) => r.id === selectedRideId);
  const selectedDriver = state.users.find((u) => u.id === selectedRide?.driverId);

  const setState = (patch: Partial<typeof state>) => update((s) => ({ ...s, ...patch }));
  const notify = (userId: string, text: string) => update((s) => ({ ...s, notifications: [{ id: `n-${Date.now()}`, userId, text, read: false, time: "Agora" }, ...s.notifications] }));
  const switchUser = () => { const id = current?.id === "bruno" ? "camila" : "bruno"; setState({ currentUserId: id }); setView("inicio"); toast.success(`Perfil alterado para ${id === "bruno" ? "Bruno Andrade" : "Camila Ribeiro"}`); };
  const login = (email: string, password: string) => { const user = state.users.find((u) => u.email.toLowerCase() === email.toLowerCase() && u.password === password); if (!user) return false; setState({ currentUserId: user.id }); toast.success(`Bem-vindo, ${user.name.split(" ")[0]}!`); return true; };
  const signup = (user: User) => { update((s) => ({ ...s, users: [...s.users, user], currentUserId: user.id })); toast.success("Conta criada com sucesso!"); };
  if (!hydrated) return <div className="grid min-h-screen place-items-center bg-background"><LoaderCircle className="size-8 animate-spin text-primary" /><span className="sr-only">Carregando UniCarona</span></div>;
  if (!current) return <Login onLogin={login} onSignup={signup} />;

  const go = (id: View) => { setView(id); setMobileMenu(false); };
  const unread = state.notifications.filter((n) => n.userId === current.id && !n.read).length;
  const content = <div className="flex min-h-0 flex-1 overflow-hidden">
    <aside className={`${mobileMenu ? "flex" : "hidden"} absolute inset-y-0 left-0 z-30 w-64 flex-col border-r bg-card p-4 shadow-xl lg:static lg:flex lg:shadow-none`}>
      <div className="mb-5 flex items-center justify-between px-2 lg:hidden"><b>Menu</b><Button variant="ghost" size="icon" onClick={() => setMobileMenu(false)}><X /></Button></div>
      <nav className="space-y-1">{menu.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => go(id)} className={`flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-sm font-medium transition-colors ${view === id ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`}><Icon className="size-4" />{label}{id === "solicitacoes" && state.requests.filter((r) => r.status === "Pendente").length > 0 && <span className="ml-auto rounded-full bg-destructive px-1.5 text-[10px] text-destructive-foreground">{state.requests.filter((r) => r.status === "Pendente").length}</span>}</button>)}</nav>
      <div className="mt-auto rounded-md bg-muted p-3"><p className="text-xs font-semibold">Protótipo local</p><p className="mt-1 text-xs text-muted-foreground">Os dados ficam apenas neste navegador.</p><Button variant="ghost" size="sm" className="mt-2 w-full" onClick={() => { reset(); toast.success("Dados de demonstração restaurados."); }}><RefreshCw /> Restaurar dados</Button></div>
    </aside>
    <main className="min-w-0 flex-1 overflow-y-auto bg-surface"><div className="mx-auto max-w-7xl p-4 sm:p-6 lg:p-8">
      <div className="mb-6 flex items-center gap-2 text-xs text-muted-foreground"><span>UniCarona</span><ChevronRight className="size-3" /><span className="font-medium text-foreground">{menu.find((i) => i.id === view)?.label}</span></div>
      {view === "inicio" && <HomeView user={current} rides={state.rides} requests={state.requests.length} go={go} />}
      {view === "buscar" && <SearchView rides={state.rides.filter((r) => r.driverId !== current.id)} users={state.users} searching={searching} onSearch={() => { setSearching(true); window.setTimeout(() => { setSearching(false); toast.success("Caronas atualizadas para seus filtros."); }, 650); }} onProfile={(id) => { setSelectedRideId(id); setModal("driver"); }} onRequest={(id) => { setSelectedRideId(id); setModal("request"); }} />}
      {view === "publicar" && <PublishView user={current} onWallet={() => setModal("wallet")} onCreate={(ride) => { update((s) => ({ ...s, rides: [ride, ...s.rides] })); toast.success("Carona publicada com sucesso!"); go("inicio"); }} />}
      {view === "solicitacoes" && <RequestsView user={current} requests={state.requests} rides={state.rides} users={state.users} onApprove={(id) => { const req = state.requests.find((r) => r.id === id); update((s) => ({ ...s, requests: s.requests.map((r) => r.id === id ? { ...r, status: "Aprovada" } : r), rides: s.rides.map((r) => r.id === req?.rideId ? { ...r, seats: Math.max(0, r.seats - 1), status: "Aprovada" } : r) })); if (req) notify(req.passengerId, "Sua vaga foi aprovada! O PIX já está disponível."); toast.success("Vaga aprovada e QR PIX gerado."); }} onReject={(id) => { setSelectedRideId(id); setConfirm("reject"); }} />}
      {view === "corrida" && <TrackingView onFinish={() => { update((s) => ({ ...s, rides: s.rides.map((r) => r.status === "Em andamento" ? { ...r, status: "Concluída" } : r) })); toast.success("Corrida finalizada. Obrigado por compartilhar o caminho!"); }} />}
      {view === "carteira" && <WalletView user={current} onConfigure={() => setModal("wallet")} />}
      {view === "painel" && <DashboardView user={current} onReceipt={() => setModal("receipt")} />}
      {view === "perfil" && <ProfileView user={current} onSave={(values) => { update((s) => ({ ...s, users: s.users.map((u) => u.id === current.id ? { ...u, ...values } : u) })); toast.success("Perfil atualizado com sucesso."); }} onLogout={() => setConfirm("logout")} onDelete={() => setConfirm("delete")} />}
    </div></main>
  </div>;

  return <div className="min-h-screen bg-workspace text-foreground">
    <div className="sticky top-0 z-50 flex h-14 items-center justify-center border-b bg-background/95 px-3 backdrop-blur">
      <div className="grid w-full max-w-7xl grid-cols-[minmax(0,1fr)_auto] items-center gap-2 sm:flex sm:justify-between"><div className="flex min-w-0 items-center gap-2"><span className="grid size-8 shrink-0 place-items-center rounded-md bg-primary text-primary-foreground"><Car className="size-4" /></span><b className="truncate">UniCarona</b><Badge variant="secondary" className="hidden sm:flex">Protótipo</Badge></div><div className="flex shrink-0 items-center gap-1 sm:gap-2"><div className="hidden rounded-md bg-muted p-1 sm:flex"><button onClick={() => setState({ displayMode: "desktop" })} className={`rounded-sm px-3 py-1.5 text-xs font-semibold ${state.displayMode === "desktop" ? "bg-card shadow-sm" : "text-muted-foreground"}`}>Visão Web Desktop</button><button onClick={() => setState({ displayMode: "mobile" })} className={`rounded-sm px-3 py-1.5 text-xs font-semibold ${state.displayMode === "mobile" ? "bg-card shadow-sm" : "text-muted-foreground"}`}>Simulador Mobile</button></div><Button variant="outline" size="sm" onClick={switchUser}><ArrowLeftRight /><span className="hidden md:inline">Alternar usuário de teste</span></Button><Sun className="hidden size-4 sm:block" /><Switch aria-label="Alternar tema" checked={state.theme === "dark"} onCheckedChange={(v) => setState({ theme: v ? "dark" : "light" })} /><Moon className="hidden size-4 sm:block" /></div></div>
    </div>
    <div className={state.displayMode === "mobile" ? "phone-stage" : "desktop-stage"}><div className={state.displayMode === "mobile" ? "phone-frame" : "app-frame"}>{state.displayMode === "mobile" && <div className="phone-status"><span>02:00</span><span className="phone-island" /><span>5G 87%</span></div>}
      <header className="grid h-16 grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3 border-b bg-card px-4"><Button variant="ghost" size="icon" onClick={() => setMobileMenu(!mobileMenu)} className="lg:hidden"><Menu /></Button><div className="hidden items-center gap-2 lg:flex"><span className="grid size-8 place-items-center rounded-md bg-primary text-primary-foreground"><Car className="size-4" /></span><b>UniCarona</b></div><div className="min-w-0 lg:ml-auto"><p className="truncate text-sm font-semibold">Olá, {current.name.split(" ")[0]}!</p><p className="truncate text-xs text-muted-foreground">{current.type === "motorista" ? "Motorista e passageiro" : "Passageira"}</p></div><div className="flex items-center gap-2"><Button variant="ghost" size="icon" className="relative"><Bell />{unread > 0 && <span className="absolute right-1 top-1 size-2 rounded-full bg-destructive" />}</Button><Avatar><AvatarFallback className="bg-primary text-primary-foreground">{current.avatar}</AvatarFallback></Avatar></div></header>
      {content}{state.displayMode === "mobile" && <nav className="mobile-tabs">{menu.slice(0, 5).map(({ id, label, icon: Icon }) => <button key={id} onClick={() => go(id)} className={view === id ? "text-primary" : "text-muted-foreground"}><Icon /><span>{label === "Buscar carona" ? "Buscar" : label === "Corrida ao vivo" ? "Corrida" : label}</span></button>)}</nav>}</div></div>
    <DriverDialog open={modal === "driver"} onClose={() => setModal(null)} driver={selectedDriver} />
    <RequestDialog open={modal === "request"} onClose={() => setModal(null)} ride={selectedRide} driver={selectedDriver} onConfirm={() => { if (!selectedRide) return; if (state.requests.some((r) => r.rideId === selectedRide.id && r.passengerId === current.id)) { toast.error("Você já solicitou esta carona."); setModal(null); return; } update((s) => ({ ...s, requests: [...s.requests, { id: `q-${Date.now()}`, rideId: selectedRide.id, passengerId: current.id, status: "Pendente", createdAt: "Agora" }] })); notify(selectedRide.driverId, `${current.name} solicitou uma vaga.`); toast.success("Solicitação enviada! Aguardando aprovação do motorista."); setModal(null); }} />
    <WalletDialog open={modal === "wallet"} onClose={() => setModal(null)} onConfirm={() => { update((s) => ({ ...s, users: s.users.map((u) => u.id === current.id ? { ...u, walletConfigured: true } : u) })); toast.success("Carteira PIX configurada com sucesso!"); setModal(null); }} />
    <ReceiptDialog open={modal === "receipt"} onClose={() => setModal(null)} user={current} />
    <AlertDialog open={confirm !== null} onOpenChange={(o) => !o && setConfirm(null)}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{confirm === "delete" ? "Excluir conta definitivamente?" : confirm === "cancel" ? "Cancelar anúncio de carona?" : confirm === "reject" ? "Recusar solicitação?" : "Deseja realmente sair da sua conta?"}</AlertDialogTitle><AlertDialogDescription>{confirm === "delete" ? "Esta ação é irreversível. Todos os seus dados serão removidos da plataforma." : confirm === "cancel" ? "Ao cancelar, os passageiros confirmados serão notificados e estornados automaticamente." : confirm === "reject" ? "A passageira será notificada e poderá procurar outra carona." : "Sua sessão será encerrada, mas os dados continuarão salvos neste navegador."}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Voltar</AlertDialogCancel><AlertDialogAction className={confirm === "logout" ? "" : "bg-destructive text-destructive-foreground hover:bg-destructive/90"} onClick={() => { if (confirm === "logout") setState({ currentUserId: null }); if (confirm === "delete") update((s) => ({ ...initialState, users: s.users.filter((u) => u.id !== current.id), currentUserId: null, theme: s.theme, displayMode: s.displayMode })); if (confirm === "cancel") update((s) => ({ ...s, rides: s.rides.map((r) => r.id === selectedRideId ? { ...r, status: "Cancelada" } : r) })); if (confirm === "reject") update((s) => ({ ...s, requests: s.requests.map((r) => r.id === selectedRideId ? { ...r, status: "Recusada" } : r) })); toast.success(confirm === "logout" ? "Você saiu da sua conta." : confirm === "delete" ? "Conta excluída." : confirm === "cancel" ? "Carona cancelada e passageiros notificados." : "Solicitação recusada."); setConfirm(null); }}>{confirm === "logout" ? "Sair" : "Confirmar"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
  </div>;
}

function PageTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="mb-6 grid grid-cols-[minmax(0,1fr)_auto] items-end gap-4"><div className="min-w-0"><p className="text-xs font-bold uppercase text-primary">{eyebrow}</p><h1 className="mt-1 text-2xl font-bold sm:text-3xl">{title}</h1><p className="mt-1 max-w-2xl text-sm text-muted-foreground">{description}</p></div>{action}</div>; }

function HomeView({ user, rides, requests, go }: { user: User; rides: Ride[]; requests: number; go: (v: View) => void }) {
  const isDriver = user.type === "motorista";
  return <><PageTitle eyebrow="Segunda-feira, 14 de setembro" title={`Boa noite, ${user.name.split(" ")[0]}`} description={isDriver ? "Acompanhe suas caronas e mantenha tudo pronto para o próximo trajeto." : "Encontre uma rota segura para o campus e acompanhe suas viagens."} action={<Button onClick={() => go(isDriver ? "publicar" : "buscar")} className="hidden sm:flex">{isDriver ? <Plus /> : <Search />}{isDriver ? "Publicar carona" : "Buscar carona"}</Button>} />
    <section className="mb-6 overflow-hidden rounded-md bg-brand-panel p-6 text-primary-foreground sm:p-8"><div className="grid items-center gap-5 md:grid-cols-[1fr_auto]"><div><Badge className="bg-primary-foreground/15 text-primary-foreground">{isDriver ? `${requests} solicitação pendente` : "Próxima carona confirmada"}</Badge><h2 className="mt-3 text-2xl font-bold">{isDriver ? "Sua próxima saída está quase completa" : "Faltam 8 minutos para o embarque"}</h2><p className="mt-2 text-sm text-primary-foreground/75">Estação Gameleira → PUC Minas Coração Eucarístico · 07:20</p></div><Button variant="secondary" onClick={() => go(isDriver ? "solicitacoes" : "corrida")}>{isDriver ? "Ver solicitações" : "Acompanhar trajeto"}<ChevronRight /></Button></div></section>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={Car} label={isDriver ? "Caronas oferecidas" : "Caronas realizadas"} value={isDriver ? "87" : "31"} note="+6 neste mês" /><StatCard icon={Users} label={isDriver ? "Passageiros transportados" : "Motoristas parceiros"} value={isDriver ? "146" : "18"} note="Comunidade verificada" /><StatCard icon={Star} label="Nota média" value={`${user.rating} ★`} note="Excelente reputação" /><StatCard icon={CircleDollarSign} label={isDriver ? "Total arrecadado" : "Economia estimada"} value={isDriver ? "R$ 862,50" : "R$ 180,00"} note="Neste semestre" /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.4fr_.6fr]"><section><h2 className="mb-3 font-bold">Próximas caronas</h2><div className="grid gap-4 md:grid-cols-2">{rides.filter((r) => r.status === "Pendente").slice(0, 2).map((r) => <RideMini key={r.id} ride={r} />)}</div></section><section><h2 className="mb-3 font-bold">Acesso rápido</h2><div className="border bg-card p-2">{[{ id: "buscar" as View, label: "Encontrar uma rota", icon: Search }, { id: "carteira" as View, label: "Minha carteira PIX", icon: WalletCards }, { id: "perfil" as View, label: "Editar meu perfil", icon: Settings }].map(({ id, label, icon: Icon }) => <button key={id} onClick={() => go(id)} className="flex w-full items-center gap-3 rounded-md p-3 text-sm font-medium hover:bg-muted"><Icon className="size-4 text-primary" />{label}<ChevronRight className="ml-auto size-4" /></button>)}</div></section></div>
  </>;
}

function RideMini({ ride }: { ride: Ride }) { return <div className="border bg-card p-4 shadow-sm"><div className="flex justify-between"><span className="text-sm font-bold">{ride.time}</span><Status value={ride.status} /></div><p className="mt-4 text-sm"><MapPin className="mr-2 inline size-4 text-primary" />{ride.origin}</p><p className="mt-2 text-sm"><Navigation className="mr-2 inline size-4 text-success" />{ride.destination}</p><div className="mt-4 flex justify-between border-t pt-3 text-xs text-muted-foreground"><span>{ride.seats} vagas</span><b className="text-foreground">R$ 6,00</b></div></div>; }

function SearchView({ rides, users, searching, onSearch, onProfile, onRequest }: { rides: Ride[]; users: User[]; searching: boolean; onSearch: () => void; onProfile: (id: string) => void; onRequest: (id: string) => void }) {
  const [origin, setOrigin] = useState("Estação Gameleira"); const [destination, setDestination] = useState("UFMG - Portaria Antônio Carlos"); const [rating, setRating] = useState("0");
  const shown = useMemo(() => rides.filter((r) => r.rating >= Number(rating) && r.status === "Pendente"), [rides, rating]);
  return <><PageTitle eyebrow="RF014" title="Buscar caronas" description="Compare horários, motoristas verificados e vagas disponíveis." /><section className="mb-6 border bg-card p-4 shadow-sm sm:p-5"><div className="grid gap-3 md:grid-cols-4"><Field label="Origem"><Input list="campuses" value={origin} onChange={(e) => setOrigin(e.target.value)} /></Field><Field label="Destino"><Input list="campuses" value={destination} onChange={(e) => setDestination(e.target.value)} /></Field><Field label="Data"><Input type="date" defaultValue="2026-09-15" /></Field><Button className="mt-auto h-10" onClick={onSearch}>{searching ? <LoaderCircle className="animate-spin" /> : <Search />} Pesquisar</Button></div><datalist id="campuses">{campuses.map((c) => <option value={c} key={c} />)}</datalist><div className="mt-4 flex flex-wrap items-center gap-2 border-t pt-4"><span className="text-xs font-semibold text-muted-foreground">Filtrar por:</span><Select value={rating} onValueChange={setRating}><SelectTrigger className="h-8 w-40"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="0">Qualquer nota</SelectItem><SelectItem value="4.8">Nota 4,8+</SelectItem><SelectItem value="4.9">Nota 4,9+</SelectItem></SelectContent></Select><Badge variant="outline">Com vagas</Badge><Badge variant="outline">Até 08:30</Badge></div></section>
    <div className="mb-4 flex items-center justify-between"><h2 className="font-bold">{shown.length} caronas encontradas</h2><span className="text-xs text-muted-foreground">Ordenadas por horário</span></div><div className="grid gap-4 xl:grid-cols-2">{shown.length ? shown.map((r) => { const d = users.find((u) => u.id === r.driverId); return d ? <RideCard key={r.id} ride={r} driver={d} onProfile={() => onProfile(r.id)} onRequest={() => onRequest(r.id)} /> : null; }) : <div className="col-span-full grid place-items-center border bg-card py-14 text-center"><Car className="size-10 text-muted-foreground" /><h3 className="mt-3 font-bold">Nenhuma carona disponível no momento</h3><p className="mt-1 text-sm text-muted-foreground">Tente mudar a nota mínima ou os locais.</p></div>}</div>
  </>;
}

function PublishView({ user, onWallet, onCreate }: { user: User; onWallet: () => void; onCreate: (ride: Ride) => void }) {
  const [origin, setOrigin] = useState("Estação Gameleira"); const [destination, setDestination] = useState("PUC Minas - Campus Coração Eucarístico"); const [date, setDate] = useState("2026-09-16"); const [time, setTime] = useState("07:20"); const [seats, setSeats] = useState("2"); const [plate, setPlate] = useState(user.vehicle?.plate ?? ""); const [vehicle, setVehicle] = useState(user.vehicle ? `${user.vehicle.model} - ${user.vehicle.color}` : ""); const [saving, setSaving] = useState(false);
  const maskPlate = (v: string) => v.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 7);
  const submit = (e: FormEvent) => { e.preventDefault(); if (!user.walletConfigured) { onWallet(); return; } if (!/^[A-Z]{3}\d[A-Z]\d{2}$/.test(plate)) return toast.error("Informe uma placa Mercosul válida, como ABC1D23."); setSaving(true); window.setTimeout(() => { onCreate({ id: `r-${Date.now()}`, driverId: user.id, origin, destination, date, time, seats: Number(seats), status: "Pendente", vehicle, plate, rating: user.rating }); setSaving(false); }, 650); };
  return <><PageTitle eyebrow="RF010 · RF011" title="Publicar uma carona" description="Informe seu trajeto. O valor é tabelado para manter a experiência justa." /><div className="grid gap-6 xl:grid-cols-[1fr_340px]"><form onSubmit={submit} className="space-y-5 border bg-card p-5 shadow-sm sm:p-6"><div className={`flex gap-3 rounded-md p-4 ${user.walletConfigured ? "bg-success-soft text-success" : "bg-warning-soft text-warning"}`}>{user.walletConfigured ? <ShieldCheck className="shrink-0" /> : <AlertTriangle className="shrink-0" />}<div><b className="block text-sm">{user.walletConfigured ? "Carteira pronta para receber" : "Carteira de recebimento pendente"}</b><p className="mt-1 text-xs">{user.walletConfigured ? "Sua chave PIX está validada para esta simulação." : "Configure sua carteira de recebimento antes de criar uma carona."}</p>{!user.walletConfigured && <Button type="button" size="sm" className="mt-3" onClick={onWallet}>Configurar PIX em 1 clique</Button>}</div></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Origem"><Input list="campuses" value={origin} onChange={(e) => setOrigin(e.target.value)} /></Field><Field label="Destino"><Input list="campuses" value={destination} onChange={(e) => setDestination(e.target.value)} /></Field><Field label="Data de partida"><Input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></Field><Field label="Horário"><Input type="time" value={time} onChange={(e) => setTime(e.target.value)} /></Field><Field label="Vagas disponíveis"><Select value={seats} onValueChange={setSeats}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{[1,2,3,4].map((n) => <SelectItem value={String(n)} key={n}>{n} {n === 1 ? "vaga" : "vagas"}</SelectItem>)}</SelectContent></Select></Field><Field label="Placa Mercosul"><Input value={plate} onChange={(e) => setPlate(maskPlate(e.target.value))} placeholder="ABC1D23" /></Field></div><Field label="Modelo e cor do veículo"><Input value={vehicle} maxLength={80} onChange={(e) => setVehicle(e.target.value)} placeholder="Chevrolet Onix 2022 - Branco" /></Field><Button className="h-11 w-full" disabled={saving}>{saving ? <LoaderCircle className="animate-spin" /> : <Plus />}{saving ? "Publicando..." : "Publicar carona"}</Button></form><aside className="h-fit border bg-card p-5 shadow-sm"><div className="flex items-center gap-2 text-primary"><CircleDollarSign /><b>Preço transparente</b></div><div className="mt-5 space-y-3 text-sm"><div className="flex justify-between"><span>Preço fixo da carona</span><b>R$ 5,25</b></div><div className="flex justify-between"><span>Taxa de conveniência</span><b>R$ 0,75</b></div><div className="flex justify-between border-t pt-4 text-base"><span className="font-bold">Total do passageiro</span><b className="text-primary">R$ 6,00</b></div></div><p className="mt-5 rounded-md bg-muted p-3 text-xs text-muted-foreground">O preço é tabelado e fixo conforme a tarifa municipal vigente. O motorista não pode alterá-lo.</p></aside></div></>;
}

function RequestsView({ user, requests, rides, users, onApprove, onReject }: { user: User; requests: ReturnType<typeof useUniCarona>["state"]["requests"]; rides: Ride[]; users: User[]; onApprove: (id: string) => void; onReject: (id: string) => void }) {
  const relevant = user.type === "motorista" ? requests.filter((q) => rides.find((r) => r.id === q.rideId)?.driverId === user.id) : requests.filter((q) => q.passengerId === user.id);
  return <><PageTitle eyebrow="RF017 · RF019" title={user.type === "motorista" ? "Solicitações recebidas" : "Minhas solicitações"} description={user.type === "motorista" ? "Conheça o perfil acadêmico antes de aprovar uma vaga." : "Acompanhe a resposta dos motoristas e o pagamento."} />{relevant.length ? <div className="space-y-4">{relevant.map((req) => { const passenger = users.find((u) => u.id === req.passengerId); const ride = rides.find((r) => r.id === req.rideId); if (!passenger || !ride) return null; return <div key={req.id} className="border bg-card p-5 shadow-sm"><div className="grid gap-5 md:grid-cols-[1fr_auto]"><div className="flex min-w-0 gap-4"><Avatar className="size-12"><AvatarFallback className="bg-primary-soft font-bold text-primary">{passenger.avatar}</AvatarFallback></Avatar><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><b>{passenger.name}</b><Status value={req.status} /></div><p className="mt-1 text-sm text-muted-foreground">{passenger.course} · {passenger.university}</p><div className="mt-2 flex flex-wrap gap-3 text-xs"><span className="flex items-center gap-1 text-success"><ShieldCheck className="size-3" /> Estudante verificada</span><span>★ {passenger.rating}</span><span>{passenger.completedRides} caronas concluídas</span></div></div></div>{user.type === "motorista" && req.status === "Pendente" && <div className="flex gap-2 self-center"><Button variant="outline" onClick={() => onReject(req.id)}>Recusar</Button><Button onClick={() => onApprove(req.id)}><Check /> Aprovar vaga</Button></div>}{req.status === "Aprovada" && <Button variant="outline" onClick={() => toast.success("QR PIX aberto para pagamento.")}><QrCode /> Ver PIX</Button>}</div><div className="mt-4 flex items-center gap-2 rounded-md bg-muted p-3 text-sm"><MapPin className="size-4 text-primary" /><span className="truncate">{ride.origin} → {ride.destination}</span><span className="ml-auto shrink-0 font-semibold">{ride.time}</span></div></div>; })}</div> : <div className="grid place-items-center border bg-card py-16 text-center"><Users className="size-10 text-muted-foreground" /><h3 className="mt-3 font-bold">Nenhuma solicitação pendente</h3><p className="mt-1 text-sm text-muted-foreground">Novas solicitações aparecerão aqui.</p></div>}</>;
}

function TrackingView({ onFinish }: { onFinish: () => void }) { const [progress, setProgress] = useState(54); return <><PageTitle eyebrow="RF032" title="Corrida em andamento" description="Acompanhe o trajeto simulado em tempo real." /><div className="relative min-h-[610px] overflow-hidden border bg-map shadow-sm"><svg viewBox="0 0 900 500" className="absolute inset-0 h-full w-full" aria-label="Mapa ilustrado de Belo Horizonte"><path d="M0 90 C160 130 130 220 300 210 S520 80 900 130M0 360 C220 290 380 400 900 300M130 0 C190 160 110 330 220 500M600 0 C540 150 700 290 650 500" fill="none" stroke="currentColor" strokeWidth="18" className="text-map-road"/><path d="M120 390 C260 330 290 235 420 270 S620 160 760 120" fill="none" stroke="currentColor" strokeWidth="8" strokeLinecap="round" className="text-primary"/><circle cx="120" cy="390" r="12" className="fill-success"/><circle cx="760" cy="120" r="12" className="fill-primary"/><g className="car-marker" transform={`translate(${120 + progress * 5.4} ${390 - progress * 2.7})`}><circle r="25" className="fill-primary opacity-20 animate-ping"/><circle r="18" className="fill-primary"/><path d="M-8 2h16l-2-8H-5z" fill="white"/></g></svg><div className="absolute left-4 right-4 top-4 flex items-center gap-3 rounded-md bg-card/95 p-4 shadow-lg backdrop-blur sm:left-6 sm:right-auto sm:w-80"><span className="grid size-10 shrink-0 place-items-center rounded-full bg-primary-soft text-primary"><Navigation /></span><div><b className="block text-sm">Motorista a caminho</b><span className="text-xs text-muted-foreground">Chegada estimada em 8 minutos</span></div></div><div className="absolute inset-x-0 bottom-0 border-t bg-card p-5 shadow-2xl sm:inset-x-6 sm:bottom-6 sm:rounded-md sm:border"><div className="grid gap-4 md:grid-cols-[1fr_auto]"><div><p className="text-xs font-bold text-primary">EM VIAGEM</p><h2 className="mt-1 font-bold">Marina Costa · Hyundai HB20 2023</h2><p className="mt-1 text-sm text-muted-foreground">Cinza · RTO2A65 · ★ 5,0</p><div className="mt-3 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full bg-primary transition-all" style={{ width: `${progress}%` }} /></div></div><div className="flex items-center gap-2"><Button variant="destructive" onClick={() => toast.error("Contato de emergência acionado na simulação.")}><Phone /> SOS</Button><Button onClick={() => { setProgress(100); window.setTimeout(onFinish, 450); }}><Check /> Simular chegada</Button></div></div></div></div></>;
}

function WalletView({ user, onConfigure }: { user: User; onConfigure: () => void }) { return <><PageTitle eyebrow="RF010" title="Carteira de recebimento" description="Simulação da conta de repasse das caronas." /><div className="grid gap-6 lg:grid-cols-[1fr_1.2fr]"><section className="overflow-hidden rounded-md bg-brand-panel p-6 text-primary-foreground"><p className="text-sm text-primary-foreground/70">Saldo disponível</p><p className="mt-2 text-4xl font-bold">R$ 186,75</p><div className="mt-8 flex justify-between border-t border-primary-foreground/20 pt-4 text-sm"><span>Próximo repasse</span><b>18 set · R$ 42,00</b></div></section><section className="border bg-card p-6"><div className="flex items-start gap-4"><span className={`grid size-11 place-items-center rounded-md ${user.walletConfigured ? "bg-success-soft text-success" : "bg-warning-soft text-warning"}`}><WalletCards /></span><div><h2 className="font-bold">{user.walletConfigured ? "Carteira PIX ativa" : "Configure sua carteira PIX"}</h2><p className="mt-1 text-sm text-muted-foreground">{user.walletConfigured ? `Chave vinculada ao e-mail ${user.email}` : "Necessária para publicar caronas e receber os repasses."}</p></div></div>{!user.walletConfigured && <Button className="mt-6" onClick={onConfigure}>Configurar agora</Button>}<div className="mt-6 border-t pt-5"><h3 className="text-sm font-bold">Últimos repasses</h3>{["Carona #UC-1842 · + R$ 10,50", "Carona #UC-1801 · + R$ 15,75", "Carona #UC-1766 · + R$ 5,25"].map((t) => <div key={t} className="flex items-center border-b py-3 text-sm"><CircleDollarSign className="mr-3 size-4 text-success" />{t}<span className="ml-auto text-xs text-muted-foreground">Concluído</span></div>)}</div></section></div></>; }

function DashboardView({ user, onReceipt }: { user: User; onReceipt: () => void }) { const driver = user.type === "motorista"; const bars = [42, 68, 55, 86, 100, 38, 22]; return <><PageTitle eyebrow={driver ? "RF037" : "RF038"} title={driver ? "Painel do motorista" : "Painel da passageira"} description="Seu impacto e histórico na mobilidade universitária." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={Car} label={driver ? "Caronas oferecidas" : "Caronas realizadas"} value={driver ? "87" : "31"} note="+12% no semestre"/><StatCard icon={Users} label={driver ? "Passageiros transportados" : "Avaliações recebidas"} value={driver ? "146" : "28"} note="98% positivas"/><StatCard icon={Star} label="Nota média" value={`${user.rating} ★`} note="Entre as melhores"/><StatCard icon={CircleDollarSign} label={driver ? "Total arrecadado" : "Total investido"} value={driver ? "R$ 862,50" : "R$ 186,00"} note={driver ? "R$ 126 este mês" : "Economia de ~R$ 180"}/></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><section className="border bg-card p-5"><div className="flex justify-between"><h2 className="font-bold">Caronas por dia</h2><Badge variant="secondary">Últimos 30 dias</Badge></div><div className="mt-8 flex h-52 items-end justify-between gap-3">{bars.map((h, i) => <div key={i} className="flex h-full flex-1 flex-col justify-end gap-2 text-center"><div className="rounded-t-sm bg-primary-soft" style={{ height: `${h}%` }}><div className="h-full bg-primary opacity-80" /></div><span className="text-xs text-muted-foreground">{["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"][i]}</span></div>)}</div></section><section className="border bg-card p-5"><h2 className="font-bold">Histórico recente</h2>{["PUC Minas → Praça da Liberdade", "Gameleira → Coração Eucarístico", "UFMG → Centro de BH"].map((r, i) => <div key={r} className="flex items-center gap-3 border-b py-4"><span className="grid size-9 shrink-0 place-items-center rounded-md bg-success-soft text-success"><Check /></span><div className="min-w-0"><p className="truncate text-sm font-semibold">{r}</p><p className="text-xs text-muted-foreground">{12 - i * 3} set · R$ 6,00</p></div><Button variant="ghost" size="icon" className="ml-auto" onClick={onReceipt}><Eye /></Button></div>)}</section></div></>; }

function ProfileView({ user, onSave, onLogout, onDelete }: { user: User; onSave: (v: Partial<User>) => void; onLogout: () => void; onDelete: () => void }) { const [name, setName] = useState(user.name); const [phone, setPhone] = useState(user.phone); const [bio, setBio] = useState(user.bio); const [university, setUniversity] = useState(user.university); return <><PageTitle eyebrow="RF006" title="Meu perfil" description="Mantenha suas informações acadêmicas e de contato atualizadas." /><div className="grid gap-6 lg:grid-cols-[260px_1fr]"><aside className="h-fit border bg-card p-5 text-center"><Avatar className="mx-auto size-24"><AvatarFallback className="bg-primary-soft text-2xl font-bold text-primary">{user.avatar}</AvatarFallback></Avatar><Button variant="outline" size="sm" className="mt-4" onClick={() => toast.success("Nova foto selecionada para a prévia.")}><Pencil /> Alterar foto</Button><h2 className="mt-4 font-bold">{user.name}</h2><p className="text-sm text-muted-foreground">{user.course}</p><Badge className="mt-3 bg-success-soft text-success"><ShieldCheck /> Acadêmico verificado</Badge></aside><section className="space-y-5 border bg-card p-5 sm:p-6"><div className="grid gap-4 sm:grid-cols-2"><Field label="Nome completo"><Input value={name} onChange={(e) => setName(e.target.value)} /></Field><Field label="Telefone"><Input value={phone} onChange={(e) => setPhone(e.target.value)} /></Field></div><Field label="Universidade"><Select value={university} onValueChange={setUniversity}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{universityOptions.map((u) => <SelectItem value={u} key={u}>{u}</SelectItem>)}</SelectContent></Select></Field><Field label="Biografia"><Textarea value={bio} maxLength={240} onChange={(e) => setBio(e.target.value)} /></Field><div className="flex flex-wrap gap-2"><Button onClick={() => onSave({ name, phone, bio, university })}>Salvar alterações</Button><Button variant="outline" onClick={onLogout}><LogOut /> Sair da conta</Button></div><div className="mt-8 rounded-md border border-destructive/30 bg-destructive-soft p-4"><h3 className="font-bold text-destructive">Zona de perigo</h3><p className="mt-1 text-sm text-destructive/80">A exclusão remove todos os dados deste perfil.</p><Button variant="destructive" className="mt-4" onClick={onDelete}><Trash2 /> Excluir conta</Button></div></section></div></>; }

function DriverDialog({ open, onClose, driver }: { open: boolean; onClose: () => void; driver?: User }) { return <Dialog open={open} onOpenChange={(o) => !o && onClose()}><DialogContent>{driver && <><DialogHeader><div className="flex items-center gap-4"><Avatar className="size-16"><AvatarFallback className="bg-primary-soft text-xl font-bold text-primary">{driver.avatar}</AvatarFallback></Avatar><div><DialogTitle>{driver.name}</DialogTitle><DialogDescription>{driver.university}</DialogDescription><Badge className="mt-2 bg-success-soft text-success"><ShieldCheck /> E-mail acadêmico verificado</Badge></div></div></DialogHeader><div className="grid grid-cols-3 gap-3 text-center"><div className="bg-muted p-3"><b>{driver.rating} ★</b><p className="text-xs text-muted-foreground">Avaliação</p></div><div className="bg-muted p-3"><b>{driver.completedRides}</b><p className="text-xs text-muted-foreground">Caronas</p></div><div className="bg-muted p-3"><b>100%</b><p className="text-xs text-muted-foreground">Verificado</p></div></div><div className="rounded-md border p-4"><b className="text-sm">Veículo</b><p className="mt-1 text-sm text-muted-foreground">{driver.vehicle?.model} · {driver.vehicle?.color} · {driver.vehicle?.plate}</p></div><div><b className="text-sm">Avaliações verificadas</b><p className="mt-2 rounded-md bg-muted p-3 text-sm">“Pontual, carro limpo e conversa ótima. Recomendo!” <span className="block pt-1 text-xs text-muted-foreground">— Estudante UFMG</span></p></div></>}</DialogContent></Dialog>; }

function RequestDialog({ open, onClose, ride, driver, onConfirm }: { open: boolean; onClose: () => void; ride?: Ride; driver?: User; onConfirm: () => void }) { return <Dialog open={open} onOpenChange={(o) => !o && onClose()}><DialogContent><DialogHeader><DialogTitle>Confirmar solicitação</DialogTitle><DialogDescription>Revise o trajeto e o valor antes de pedir sua vaga.</DialogDescription></DialogHeader>{ride && <div className="space-y-3 rounded-md bg-muted p-4 text-sm"><p><b>Motorista:</b> {driver?.name}</p><p><b>Origem:</b> {ride.origin}</p><p><b>Destino:</b> {ride.destination}</p><p><b>Embarque:</b> {ride.date.split("-").reverse().join("/")} às {ride.time}</p><div className="flex justify-between border-t pt-3 text-base"><b>Total a pagar</b><b className="text-primary">R$ 6,00</b></div></div>}<DialogFooter><Button variant="outline" onClick={onClose}>Voltar</Button><Button onClick={onConfirm}>Confirmar e solicitar</Button></DialogFooter></DialogContent></Dialog>; }

function WalletDialog({ open, onClose, onConfirm }: { open: boolean; onClose: () => void; onConfirm: () => void }) { return <Dialog open={open} onOpenChange={(o) => !o && onClose()}><DialogContent><DialogHeader><DialogTitle>Configurar carteira de recebimento</DialogTitle><DialogDescription>Esta é uma simulação. Nenhum dado bancário real será enviado.</DialogDescription></DialogHeader><div className="rounded-md bg-primary-soft p-5 text-center"><QrCode className="mx-auto size-12 text-primary" /><p className="mt-3 font-bold">Chave PIX por e-mail</p><p className="mt-1 text-sm text-muted-foreground">O repasse ficará disponível após cada carona concluída.</p></div><DialogFooter><Button variant="outline" onClick={onClose}>Agora não</Button><Button onClick={onConfirm}><ShieldCheck /> Ativar carteira simulada</Button></DialogFooter></DialogContent></Dialog>; }

function ReceiptDialog({ open, onClose, user }: { open: boolean; onClose: () => void; user: User }) { return <Dialog open={open} onOpenChange={(o) => !o && onClose()}><DialogContent><DialogHeader><DialogTitle>Recibo da carona #UC-1842</DialogTitle><DialogDescription>Comprovante gerado em 12 de setembro de 2026.</DialogDescription></DialogHeader><div className="space-y-3 rounded-md border p-4 text-sm"><div className="flex justify-between"><span>Passageiro</span><b>{user.name}</b></div><div className="flex justify-between"><span>Trajeto</span><b>Gameleira → PUC Minas</b></div><div className="flex justify-between"><span>Tarifa municipal</span><b>R$ 5,25</b></div><div className="flex justify-between"><span>Conveniência</span><b>R$ 0,75</b></div><div className="flex justify-between border-t pt-3 text-base"><b>Total pago</b><b className="text-primary">R$ 6,00</b></div></div><DialogFooter><Button onClick={() => toast.success("Recibo baixado na simulação.")}><Download /> Baixar recibo</Button></DialogFooter></DialogContent></Dialog>; }